/**
 * Minimal, dependency-free replacements for the handful of lodash helpers this package used.
 * Like their lodash counterparts, the collection helpers tolerate `undefined` collections.
 */

export function isNil(value: unknown): value is null | undefined {
  return value === null || value === undefined;
}

export function isString(value: unknown): value is string {
  return typeof value === 'string';
}

export function isPlainObject(value: unknown): value is object {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === null || prototype === Object.prototype;
}

export function isEmpty(value: unknown): boolean {
  if (isNil(value)) {
    return true;
  }

  if (isString(value) || Array.isArray(value)) {
    return value.length === 0;
  }

  if (value instanceof Map || value instanceof Set) {
    return value.size === 0;
  }

  if (typeof value === 'object') {
    return Object.keys(value as object).length === 0;
  }

  return true;
}

export function each<T>(collection: readonly T[] | Record<PropertyKey, T> | undefined, iteratee: (item: T) => void): void {
  if (isNil(collection)) {
    return;
  }

  const items: readonly T[] = Array.isArray(collection) ? collection : Object.values(collection);
  items.forEach(item => iteratee(item));
}

export function filter<T, Narrowed extends T>(collection: readonly T[] | undefined, predicate: (item: T) => item is Narrowed): Narrowed[];
export function filter<T>(collection: readonly T[] | undefined, predicate: (item: T) => boolean): T[];
export function filter<T>(collection: readonly T[] | undefined, predicate: (item: T) => boolean): T[] {
  return collection?.filter(item => predicate(item)) ?? [];
}

export function find<T>(collection: readonly T[] | undefined, predicate: (item: T) => boolean): T | undefined {
  return collection?.find(item => predicate(item));
}

export function some<T>(collection: ArrayLike<T> | undefined, predicate: (item: T) => boolean): boolean {
  return isNil(collection) ? false : Array.prototype.some.call(collection, (item: T) => predicate(item));
}

export function includes<T>(collection: readonly T[] | undefined, value: T): boolean {
  return collection?.includes(value) ?? false;
}
